program_code='''from collections import Counter


def transform(grid):
    height = len(grid)
    width = len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]

    bands = []
    row_index = 0
    while row_index < height:
        if all(value == background for value in grid[row_index]):
            row_index += 1
            continue
        start = row_index
        while row_index < height and any(value != background for value in grid[row_index]):
            row_index += 1
        rows = [
            {column for column, value in enumerate(grid[r]) if value != background}
            for r in range(start, row_index)
        ]
        bands.append((start, row_index, rows))

    out = [row[:] for row in grid]
    for target_index, (target_start, _, target_rows) in enumerate(bands):
        target_count = sum(len(row) for row in target_rows)
        sources = [
            band for source_index, band in enumerate(bands)
            if source_index != target_index
            and len(band[2]) == len(target_rows)
            and sum(len(row) for row in band[2]) > target_count
        ]
        if not sources:
            continue

        largest_count = max(sum(len(row) for row in band[2]) for band in sources)
        sources = [band for band in sources if sum(len(row) for row in band[2]) == largest_count]
        simple_rows = target_rows + sources[0][2]
        straight_runs = all(
            row == set(range(min(row), max(row) + 1))
            for row in simple_rows
        )
        shifts = (0,) if straight_runs else range(-width + 1, width)
        best = None

        for source_start, _, source_rows in sources:
            for shift in shifts:
                missing = []
                extra_count = 0
                for offset, (source_row, target_row) in enumerate(zip(source_rows, target_rows)):
                    shifted = {column + shift for column in source_row if 0 <= column + shift < width}
                    missing.extend((target_start + offset, column) for column in shifted - target_row)
                    extra_count += len(target_row - shifted)
                difference_count = len(missing) + extra_count
                candidate = (difference_count, extra_count, abs(shift), missing, source_start, shift)
                if best is None or candidate[:3] < best[:3]:
                    best = candidate

        difference_count, extra_count, _, missing, _, _ = best
        if missing and (extra_count == 0 or difference_count / largest_count <= 0.30):
            for r, c in missing:
                out[r][c] = 1

    return out
